import type { CryptoAlgorithm, CryptoProvider } from '@kokuin/crypto'
import { bytesToHex, hexToBytes } from '@noble/hashes/utils.js'

// Regenerated by scripts/import-crypto-vectors.mjs and also read by
// crates/kokuin-crypto/tests/external.rs. Keep the path stable.
import data from '../vectors/external.json' with { type: 'json' }

export type ExternalSource = {
  repository: string
  commit: string
  file: string
  sha256: string
  license: string
  note?: string
}
export type ExternalSignCase = {
  source: string
  id: string
  seed: string
  publicKey: string
  message: string
  signature: string
}
export type ExternalVerifyCase = {
  source: string
  id: string
  alg: CryptoAlgorithm
  publicKey: string
  message: string
  signature: string
  /** Expected outcome under this project's verification policy. */
  valid: boolean
  /** The source's own verdict, kept for traceability. */
  upstream: 'valid' | 'invalid' | 'acceptable'
  flags: Array<string>
}
export type ExternalHashCase = {
  source: string
  id: string
  /** Bytes of the repeating sequence 0, 1, ..., 250. */
  inputLength: number
  /** The first 131 bytes of output. */
  hash: string
}
export type ExternalVectors = {
  description: string
  sources: Record<string, ExternalSource>
  ed25519Sign: Array<ExternalSignCase>
  verify: Array<ExternalVerifyCase>
  blake3: Array<ExternalHashCase>
}

export const externalVectors: ExternalVectors = data as ExternalVectors

export type ExternalConformanceCase = { name: string; run(): Promise<void> }

function failures(label: string, ids: Array<string>): void {
  if (ids.length !== 0) {
    throw new Error(`External conformance: ${label} failed for ${ids.length}: ${ids.join(', ')}`)
  }
}

function patternInput(length: number): Uint8Array {
  return Uint8Array.from({ length }, (_, index) => index % 251)
}

/**
 * Pinned upstream vectors (Wycheproof Ed25519 and ECDSA P-256, SUPERCOP/RFC 8032 Ed25519 signing,
 * official blake3), grouped into one case per source. Separate from `cryptoConformance` because
 * running about a thousand vectors through a slow backend on a device takes a while.
 */
export function externalConformance(provider: CryptoProvider): Array<ExternalConformanceCase> {
  const cases: Array<ExternalConformanceCase> = [
    {
      name: 'external sign: supercop-ed25519 (includes RFC 8032 TEST 1-3)',
      async run() {
        const wrong: Array<string> = []
        for (const entry of externalVectors.ed25519Sign) {
          const signature = await provider.sign(
            'EdDSA',
            hexToBytes(entry.seed),
            hexToBytes(entry.message),
          )
          if (bytesToHex(signature) !== entry.signature) wrong.push(entry.id)
        }
        failures('supercop-ed25519 signing', wrong)
      },
    },
  ]
  const sources = [...new Set(externalVectors.verify.map((entry) => entry.source))]
  for (const source of sources) {
    const entries = externalVectors.verify.filter((entry) => entry.source === source)
    cases.push({
      name: `external verify: ${source}`,
      async run() {
        const items = entries.map((entry) => {
          return {
            alg: entry.alg,
            signature: hexToBytes(entry.signature),
            message: hexToBytes(entry.message),
            publicKey: hexToBytes(entry.publicKey),
          }
        })
        const wrong: Array<string> = []
        for (const [index, item] of items.entries()) {
          const entry = entries[index] as ExternalVerifyCase
          const result = await provider.verify({
            alg: item.alg,
            signature: item.signature,
            message: item.message,
            publicKey: item.publicKey,
          })
          if (result !== entry.valid) wrong.push(`${entry.id} (verify returned ${result})`)
        }
        const batch = await provider.verifyBatch(items)
        if (batch.length !== items.length) wrong.push('verifyBatch length')
        batch.forEach((result, index) => {
          const entry = entries[index] as ExternalVerifyCase
          if (result !== entry.valid) wrong.push(`${entry.id} (verifyBatch returned ${result})`)
        })
        failures(source, wrong)
      },
    })
  }
  cases.push({
    name: 'external blake3: blake3-official',
    async run() {
      const wrong: Array<string> = []
      for (const entry of externalVectors.blake3) {
        const input = patternInput(entry.inputLength)
        for (const length of [32, 131]) {
          const output = await provider.blake3(input, length)
          if (bytesToHex(output) !== entry.hash.slice(0, length * 2)) {
            wrong.push(`${entry.id}/${length}`)
          }
        }
      }
      failures('blake3-official', wrong)
    },
  })
  return cases
}
